using MaintenancePRO.Api.Data;using MaintenancePRO.Api.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/equipment"),Authorize]
public sealed class EquipmentController(AppDbContext db):ControllerBase{
[HttpGet] public async Task<IActionResult> List([FromQuery]string? search,[FromQuery]EquipmentStatus? status){var q=db.Equipments.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Code.Contains(search)||x.Name.Contains(search)||x.Location.Contains(search));if(status.HasValue)q=q.Where(x=>x.Status==status);return Ok(await q.OrderBy(x=>x.Code).ToListAsync());}
[HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await db.Equipments.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():Ok(x);}
[HttpPost,Authorize(Policy="ManageEquipment")] public async Task<IActionResult> Create(Equipment x){if(!ModelState.IsValid)return ValidationProblem(ModelState);x.Id=0;x.Code=x.Code.Trim();if(await db.Equipments.AnyAsync(e=>e.Code==x.Code))return Conflict(new{message="Code déjà utilisé."});db.Equipments.Add(x);await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
[HttpPut("{id:int}"),Authorize(Policy="ManageEquipment")] public async Task<IActionResult> Update(int id,Equipment r){var x=await db.Equipments.FindAsync(id);if(x==null)return NotFound();x.Name=r.Name.Trim();x.Location=r.Location.Trim();x.Category=r.Category.Trim();x.Status=r.Status;await db.SaveChangesAsync();return Ok(x);}
[HttpDelete("{id:int}"),Authorize(Policy="AdminOnly")] public async Task<IActionResult> Delete(int id){var x=await db.Equipments.FindAsync(id);if(x==null)return NotFound();if(await db.Interventions.AnyAsync(i=>i.EquipmentCode==x.Code))return Conflict(new{message="Équipement référencé par des interventions."});db.Equipments.Remove(x);await db.SaveChangesAsync();return NoContent();}}
